:root {
  --color-bg: #fff8f5;
  --color-border: #f0c4ae;
  --color-header-bg: #f96e2a;
  --color-header-text: #ffffff;
  --color-badge-bg: #ffffff;
  --color-badge-text: #f96e2a;
  --color-name: #2d1a0e;
  --color-sub: #a0522d;
  --color-dot: #f96e2a;
  --color-ingredient: #3d2010;
  --color-footer-bg: #fde8d8;
  --color-footer-text: #7a3b1e;
}

.recipe-tag {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 16px;
  width: 340px;
  overflow: hidden;
  font-size: 14px;
}

.tag-header {
  background-color: var(--color-header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.tag-emoji {
  font-size: 28px;
  line-height: 1;
}

.tag-title {
  flex: 1;
}

.recipe-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--color-header-text);
  margin: 0;
  line-height: 1.2;
}

.recipe-sub {
  font-size: 11px;
  color: var(--color-header-text);
  margin: 2px 0 0;
  opacity: 0.85;
}

.tag-badge {
  background-color: var(--color-badge-bg);
  color: var(--color-badge-text);
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  letter-spacing: 0.08em;
}

.ingredient-list {
  list-style: none;
  margin: 0;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ingredient {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--color-ingredient);
  font-size: 13px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--color-dot);
  flex-shrink: 0;
}

.tag-footer {
  background-color: var(--color-footer-bg);
  display: flex;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--color-border);
}

.tag-cal,
.tag-time,
.tag-serve {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-footer-text);
}
